def babylonian_squareroot(number):
    """Compute the square root using the Babylonian (Heron's) method."""
    if number < 0:
        raise ValueError("cannot compute square root of negative number")
    if number == 0:
        return 0.0
    x = number / 2.0
    if x == 0.0:
        x = 1.0
    prev = None
    for _ in range(1000):
        y = (x + number / x) / 2.0
        if y == x or y == prev:
            return y
        prev = x
        x = y
    return x
